class Emitter {
  constructor() { this.listeners = {}; }
  on(e, fn) { (this.listeners[e] ||= []).push(fn); }
  off(e, fn) {
    const list = this.listeners[e];
    const i = list.indexOf(fn);
    if (i !== -1) list.splice(i, 1);
  }
  once(e, fn) {
    const wrapper = (...args) => { this.off(e, wrapper); fn(...args); };
    this.on(e, wrapper);
  }
  emit(e, ...args) { (this.listeners[e] || []).forEach((f) => f(...args)); }
}
const em = new Emitter();
em.once("tick", () => console.log("A"));
em.on("tick", () => console.log("B"));
em.emit("tick");
em.emit("tick");
```

