What does `twoSum([3, 2, 4], 6)` return?

```js
function twoSum(nums, target) {
  const seen = new Map();
  nums.forEach((n, i) => seen.set(n, i));
  for (let i = 0; i < nums.length; i++) {
    const j = seen.get(target - nums[i]);
    if (j !== undefined) return [i, j];
  }
  return null;
}
